"""Fixed-width EXPORT_ACCT record formatter."""

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


def _is_blank(value: Any) -> bool:
    return value is None or (isinstance(value, str) and value.strip() == "")


def _fixed(value: Any, width: int) -> str:
    text = "" if value is None else str(value)
    return text[:width].ljust(width)


def _zpad_cents(value: Any, width: int) -> str:
    amount = Decimal(0) if _is_blank(value) else Decimal(str(value))
    cents = int((amount * Decimal(100)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    return f"{cents:0{width}d}"


def format_account(row: dict) -> str:
    """Build one 77-character EXPORT_ACCT fixed-width record."""
    cred_hold = row.get("CRED_HOLD")
    if _is_blank(cred_hold):
        cred_hold = "N"
    else:
        cred_hold = str(cred_hold)

    create_dt = row.get("CREATE_DT")
    if _is_blank(create_dt):
        create_dt = "00000000"
    else:
        create_dt = str(create_dt)

    return (
        _fixed(row.get("ACCT_ID"), 10)
        + _fixed(row.get("ACCT_NM"), 40)
        + _fixed(row.get("REGION_CD"), 3)
        + _zpad_cents(row.get("ANN_REV"), 15)
        + cred_hold
        + create_dt
    )
